import { useCallback, useState } from 'react';
import {
  SegmentedControl,
  Slider,
  Switch,
  Select,
  Divider,
  Badge,
  Heading,
  Text,
} from '@jinx-ui/react';

type Theme = 'brutal' | 'glass' | 'minimal';
type Font = 'system' | 'serif' | 'mono';

interface AppearanceState {
  theme: Theme;
  scale: number;
  dense: boolean;
  font: Font;
}

interface AppearanceSettingsScreenProps {
  onChange?: (state: AppearanceState) => void;
}

const THEME_OPTIONS: { label: string; value: Theme }[] = [
  { label: 'Brutal', value: 'brutal' },
  { label: 'Glass', value: 'glass' },
  { label: 'Minimal', value: 'minimal' },
];

const FONT_OPTIONS: { label: string; value: Font }[] = [
  { label: 'Системный', value: 'system' },
  { label: 'С засечками', value: 'serif' },
  { label: 'Моноширинный', value: 'mono' },
];

const THEME_LABEL: Record<Theme, string> = {
  brutal: 'Brutal',
  glass: 'Glass',
  minimal: 'Minimal',
};

export default function AppearanceSettingsScreen({
  onChange,
}: AppearanceSettingsScreenProps) {
  const [theme, setTheme] = useState<Theme>('brutal');
  const [scale, setScale] = useState(100);
  const [dense, setDense] = useState(false);
  const [font, setFont] = useState<Font>('system');

  const emit = useCallback(
    (next: Partial<AppearanceState>) => {
      onChange?.({
        theme,
        scale,
        dense,
        font,
        ...next,
      });
    },
    [onChange, theme, scale, dense, font]
  );

  const handleThemeChange = (value: Theme) => {
    setTheme(value);
    emit({ theme: value });
  };

  const handleScaleChange = (value: number) => {
    setScale(value);
    emit({ scale: value });
  };

  const handleDenseChange = (checked: boolean) => {
    setDense(checked);
    emit({ dense: checked });
  };

  const handleFontChange = (value: Font) => {
    setFont(value);
    emit({ font: value });
  };

  return (
    <div
      className="jx-panel"
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-5)',
        padding: 'var(--jx-space-5)',
      }}
    >
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 'var(--jx-space-3)',
        }}
      >
        <Heading level={2}>Внешний вид</Heading>
        <Badge variant="outline">{THEME_LABEL[theme]}</Badge>
      </div>

      <div
        style={{
          display: 'flex',
          flexDirection: 'column',
          gap: 'var(--jx-space-2)',
        }}
      >
        <Text as="label" size="sm" weight="medium">
          Тема
        </Text>
        <SegmentedControl
          options={THEME_OPTIONS}
          value={theme}
          onValueChange={handleThemeChange}
        />
      </div>

      <div
        style={{
          display: 'flex',
          flexDirection: 'column',
          gap: 'var(--jx-space-2)',
        }}
      >
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
          }}
        >
          <Text as="label" size="sm" weight="medium">
            Масштаб интерфейса
          </Text>
          <Text size="sm" tone="muted">
            {scale}%
          </Text>
        </div>
        <Slider
          min={80}
          max={140}
          step={5}
          value={scale}
          onValueChange={handleScaleChange}
        />
      </div>

      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 'var(--jx-space-3)',
        }}
      >
        <div
          style={{
            display: 'flex',
            flexDirection: 'column',
          }}
        >
          <Text as="label" size="sm" weight="medium">
            Плотная вёрстка
          </Text>
          <Text size="sm" tone="muted">
            Уменьшает отступы между элементами
          </Text>
        </div>
        <Switch checked={dense} onCheckedChange={handleDenseChange} />
      </div>

      <Divider />

      <div
        style={{
          display: 'flex',
          flexDirection: 'column',
          gap: 'var(--jx-space-3)',
        }}
      >
        <Heading level={3}>Ещё</Heading>
        <div
          style={{
            display: 'flex',
            flexDirection: 'column',
            gap: 'var(--jx-space-2)',
          }}
        >
          <Text as="label" size="sm" weight="medium">
            Шрифт
          </Text>
          <Select
            options={FONT_OPTIONS}
            value={font}
            onValueChange={handleFontChange}
          />
        </div>
      </div>
    </div>
  );
}

